mapper.update:
UPDATE settlement_config
SET settle_days=#{settleDays},fee_rate=#{feeRate},enabled=#{enabled},
    lakala_merchant_no=#{lakalaMerchantNo},lakala_term_no=#{lakalaTermNo},
    version=version+1,updated_at=#{now}
WHERE id=#{id} AND version=#{version}

UPDATE settlement_order
SET status='SPLIT_SUCCEEDED',actual_merchant_amount=#{actualMerchantAmount},
    channel_split_fee=#{channelSplitFee},last_error_code=NULL,last_error_message=NULL,
    version=version+1,updated_at=#{now}
WHERE id=#{id} AND version=#{version} AND status='SPLITTING' AND active_instruction_id=#{instructionId}

UPDATE settlement_order
SET status='SPLIT_FAILED',last_error_code=#{errorCode},last_error_message=#{errorMessage},
    version=version+1,updated_at=#{now}
WHERE id=#{id} AND version=#{version} AND status='SPLITTING' AND active_instruction_id=#{instructionId}

UPDATE settlement_order
SET status=#{newStatus},reversed_amount=#{reversedAmount},
    last_error_code=NULL,last_error_message=NULL,
    version=version+1,updated_at=#{now}
WHERE id=#{id} AND version=#{version} AND status='REVERSING' AND active_instruction_id=#{instructionId}

UPDATE settlement_order
SET refunded_amount=#{refundedAmount},split_base=#{splitBase},merchant_share=#{merchantShare},
    platform_subsidy_due=#{platformSubsidyDue},version=version+1,updated_at=#{now}
WHERE id=#{id} AND version=#{version}
  AND status IN ('SPLIT_SUCCEEDED','REVERSING','PARTIALLY_REVERSED','REVERSED','REVERSE_FAILED')

UPDATE settlement_order
SET status='WAITING',hold_reason=NULL,last_error_code=NULL,last_error_message=NULL,
    due_schedule_round=#{dueScheduleRound},version=version+1,updated_at=#{now}
WHERE id=#{id} AND version=#{version} AND status=#{expectedStatus}

mapper.select:
SELECT  FROM settlement_order

  AND merchant_id=#{merchantId}
  AND status=#{status}

ORDER BY created_at DESC, id DESC
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*) FROM settlement_order

  AND merchant_id=#{merchantId}
  AND status=#{status}

SELECT  FROM settlement_instruction
WHERE settlement_order_id=#{settlementOrderId}
ORDER BY created_at ASC, id ASC
